import React from 'react';
import styled from 'styled-components';

const GalleryContainer = styled.div`
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
`;

const Title = styled.h1`
  font-size: 36px;
  margin-bottom: 20px;
`;

const ImageGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 15px;
  padding: 20px;
`;

const Image = styled.img`
  width: 100%;
  height: auto;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s ease;

  &:hover {
    transform: scale(1.05);
  }
`;

const Gallery = () => {
  // Directly add photo links here
  const images = [
    'C:/Users/attiullah.khanniazi/Downloads/zahid/13.jpg', // Replace with your image URLs
    'C:/Users/attiullah.khanniazi/Downloads/zahid/11.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/3.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/4.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/5.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/6.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/7.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/8.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/9.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/10.jpg',
    'C:/Users/attiullah.khanniazi/Downloads/zahid/11.jpg',
  ];

  return (
    <GalleryContainer>
      <Title>Gallery</Title>
      <ImageGrid>
        {images.map((image, index) => (
          <Image key={index} src={image} alt={`Gallery item ${index + 1}`} />
        ))}
      </ImageGrid>
    </GalleryContainer>
  );
};

export default Gallery;
